import Foundation
import OSLog

/// Reads and writes the saved session (issue #46) — the file behind `SessionSnapshot`.
///
/// **Every operation is best-effort.** The app must behave identically with the file absent, empty,
/// unreadable, or corrupt: a session that fails to load is a launch with no restore, never an error
/// the user sees. Failures log and are swallowed.
///
/// The URL is injectable so unit tests point at a temp directory — which also keeps the whole
/// feature clear of `Defaults`, and therefore clear of the single-writer rule parallel test workers
/// impose on a shared UserDefaults domain (`SharedPrefDefaultsTests`).
final class SessionStore {
  /// Where the file lives, **scoped by bundle id**.
  ///
  /// The scoping is mandatory, not tidiness: `GhosttyApp` already writes into
  /// `Application Support/Workroom/` from all three identities (Workroom, Workroom Dev, Workroom
  /// Nightly), so an unscoped path would let a Dev run's fixture temp-dir workrooms be restored into
  /// the release build. UserDefaults gets that separation free from the bundle id; a file has to buy
  /// it back.
  static func defaultURL(
    bundleID: String? = Bundle.main.bundleIdentifier,
    fileManager: FileManager = .default
  ) -> URL {
    let root = fileManager.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
      .appendingPathComponent("Workroom", isDirectory: true)
      .appendingPathComponent(bundleID ?? "com.developwithstyle.workroom", isDirectory: true)
    return root.appendingPathComponent("session.json")
  }

  /// The store production and the UI tests should use.
  ///
  /// In fixture mode this is a **no-op unless a test names a file**. The path is bundle-id scoped, so
  /// a fixture launch would otherwise write over the developer's own `Workroom Dev` session — and the
  /// fixture's temp-directory workrooms would then be restored into a real launch.
  static func forCurrentEnvironment() -> SessionStore {
    // Unit tests inject their own store, but `AppStore.markSessionDirty` reaches the SHARED
    // coordinator — so without this a `make app-test` run writes the developer's own `Workroom Dev`
    // session file and scrollback sidecars as a side effect of exercising tab mutations. Same
    // isolation the app already applies at `WorkroomApp.swift:42` and `AppStore.swift:750`.
    if ProcessInfo.processInfo.environment["XCTestConfigurationFilePath"] != nil,
      UITestFixture.sessionFilePath == nil
    {
      return SessionStore(url: SessionStore.defaultURL(), isDisabled: true)
    }
    guard UITestFixture.isActive else { return SessionStore() }
    guard let path = UITestFixture.sessionFilePath else {
      return SessionStore(url: SessionStore.defaultURL(), isDisabled: true)
    }
    return SessionStore(url: URL(fileURLWithPath: path))
  }

  let url: URL
  /// A disabled store reads nothing and writes nothing — fixture mode without a named session file.
  private let isDisabled: Bool
  /// Where an undecodable file is moved once, so a bug report has something to attach instead of the
  /// evidence being deleted.
  var quarantineURL: URL {
    url.deletingLastPathComponent().appendingPathComponent("session.corrupt.json")
  }

  /// True once a file written by a NEWER schema has been read. Every write is then refused for the
  /// rest of the run — otherwise this build silently destroys a session it could not understand, and
  /// three build identities ship side by side, so that rollback is a real path rather than a
  /// hypothetical one.
  private(set) var writesDisabled = false

  private let fileManager: FileManager
  private let logger = Logger(
    subsystem: "com.developwithstyle.workroom", category: "session")
  /// Encoding and the write happen here so neither runs on the main actor; only the capture does.
  private let queue = DispatchQueue(
    label: "com.developwithstyle.workroom.session", qos: .utility)

  init(
    url: URL = SessionStore.defaultURL(), fileManager: FileManager = .default,
    isDisabled: Bool = false
  ) {
    self.url = url
    self.fileManager = fileManager
    self.isDisabled = isDisabled
  }

  // MARK: Read

  enum ReadOutcome: Equatable {
    /// Nothing usable — a fresh install, an unreadable file, or one this build cannot decode. The
    /// caller falls back to its cold-start path.
    case none
    case restored(SessionFile, SessionSanitizeReport)
    /// Written by a newer build: restore nothing, and `writesDisabled` is now true.
    case newerSchema

    static func == (lhs: ReadOutcome, rhs: ReadOutcome) -> Bool {
      switch (lhs, rhs) {
      case (.none, .none), (.newerSchema, .newerSchema): return true
      case (.restored(let lf, let lr), .restored(let rf, let rr)):
        return lf.windows == rf.windows && lf.schemaVersion == rf.schemaVersion && lr == rr
      default: return false
      }
    }
  }

  func read() -> ReadOutcome {
    guard !isDisabled, fileManager.fileExists(atPath: url.path) else { return .none }

    // Refused BEFORE decoding: the element caps in `SessionLimits` bound how many things a file
    // describes, not how many bytes one of them spends.
    if let size = try? fileManager.attributesOfItem(atPath: url.path)[.size] as? Int,
      size > SessionLimits.maxFileBytes
    {
      logger.error("session file is \(size) bytes, over the limit — quarantining")
      quarantine()
      return .none
    }

    guard let data = try? Data(contentsOf: url) else {
      logger.error("session file unreadable")
      return .none
    }
    guard !data.isEmpty else { return .none }

    let decoder = JSONDecoder()
    decoder.dateDecodingStrategy = .iso8601
    guard let file = try? decoder.decode(SessionFile.self, from: data) else {
      logger.error("session file could not be decoded — quarantining")
      quarantine()
      return .none
    }

    switch file.compatibility {
    case .newer:
      let message =
        "session file schema \(file.schemaVersion) is newer than "
        + "\(SessionFile.currentSchemaVersion) — not restoring, writes disabled for this run"
      logger.notice("\(message, privacy: .public)")
      writesDisabled = true
      return .newerSchema
    case .unreadable:
      logger.notice("session file schema \(file.schemaVersion) has no migration — discarding")
      return .none
    case .current:
      break
    }

    let (sanitized, report) = file.sanitized()
    if !report.isEmpty {
      logger.notice("session file dropped entries — \(report.summary, privacy: .public)")
    }
    // A file whose windows all dropped is not a session. Saying so lets the caller take its
    // cold-start fallback instead of launching emptier than deleting the file would have.
    guard !sanitized.windows.isEmpty else { return .none }
    return .restored(sanitized, report)
  }

  // MARK: Write

  /// Persist off the main actor. Coalescing is the caller's job (see `AppStore+Session`).
  ///
  /// `completion` reports on the main actor whether the bytes actually reached disk. The caller needs
  /// it: it gates a write on "did this change since last time?", and treating a failed write as
  /// written would suppress every retry of the same state until something else changed.
  func write(_ file: SessionFile, completion: (@MainActor (Bool) -> Void)? = nil) {
    guard !isDisabled, !writesDisabled else {
      if let completion {
        DispatchQueue.main.async { MainActor.assumeIsolated { completion(false) } }
      }
      return
    }
    queue.async { [weak self] in
      let ok = self?.persist(file) ?? false
      guard let completion else { return }
      DispatchQueue.main.async { MainActor.assumeIsolated { completion(ok) } }
    }
  }

  /// Persist before returning — the quit path, where the process may not survive long enough for an
  /// async write to land.
  @discardableResult
  func writeSynchronously(_ file: SessionFile) -> Bool {
    guard !isDisabled, !writesDisabled else { return false }
    return queue.sync { self.persist(file) }
  }

  func clear() {
    guard !isDisabled else { return }
    queue.sync { try? self.fileManager.removeItem(at: self.url) }
  }

  // MARK: Scrollback sidecars (issue #144)

  /// One plain-text file per pane, beside `session.json`. Deliberately NOT inside it: that document
  /// is rewritten on every coalesced save, and a few hundred KB of terminal output per pane has no
  /// business riding along with the layout.
  var scrollbackDirectory: URL {
    url.deletingLastPathComponent().appendingPathComponent("scrollback", isDirectory: true)
  }

  /// Rejects a key that could address anything outside the scrollback directory.
  ///
  /// The keys this app writes are `TabSession.key` UUID strings, which are filesystem-safe by
  /// construction — but `session.json` is a plain file a user (or anything running as them) can edit,
  /// and `URL.appendingPathComponent` does **not** normalise: a key of `../../../x` yields a path
  /// that escapes on access (measured). Since `readScrollback` *deletes* a file that fails
  /// validation, an unchecked key is an arbitrary-file-delete primitive at launch.
  ///
  /// A separator check rather than a strict UUID match, so the rule bites the actual hazard without
  /// making the key format part of the on-disk contract.
  nonisolated static func isSafeScrollbackKey(_ key: String) -> Bool {
    guard !key.isEmpty, key.count <= 128, !key.hasPrefix(".") else { return false }
    return !key.contains("/") && !key.contains(":") && !key.contains("\0")
  }

  private func scrollbackURL(forTabKey key: String) -> URL? {
    guard Self.isSafeScrollbackKey(key) else {
      logger.error("refusing an unsafe scrollback key")
      return nil
    }
    return scrollbackDirectory.appendingPathComponent("\(key).txt")
  }

  func writeScrollback(_ text: String, forTabKey key: String) {
    guard !isDisabled, !writesDisabled, !text.isEmpty else { return }
    guard let fileURL = scrollbackURL(forTabKey: key) else { return }
    do {
      // Owner-only, on the directory as well as the file: a sidecar is verbatim terminal output, so
      // it can hold whatever the user's shell printed — tokens, `env` dumps, connection strings. The
      // default 0644 would leave that readable by every other account on the machine.
      try fileManager.createDirectory(
        at: scrollbackDirectory, withIntermediateDirectories: true,
        attributes: [.posixPermissions: 0o700])
      try Data(text.utf8).write(to: fileURL, options: .atomic)
      // `.atomic` writes a temp file and renames, so the mode has to be set after the rename.
      try? fileManager.setAttributes([.posixPermissions: 0o600], ofItemAtPath: fileURL.path)
    } catch {
      // Best-effort like everything else here: a pane with no sidecar simply restores empty.
      logger.error("scrollback write failed: \(error.localizedDescription)")
    }
  }

  /// The saved text for a pane, or nil when there is none, it is unreadable, or it fails validation.
  ///
  /// A file that fails validation is **deleted**: it would fail identically on every future launch,
  /// and unlike `session.json` a scrollback sidecar has no diagnostic value worth quarantining.
  func readScrollback(forTabKey key: String) -> String? {
    guard !isDisabled, let fileURL = scrollbackURL(forTabKey: key) else { return nil }
    guard fileManager.fileExists(atPath: fileURL.path) else { return nil }

    if let size = try? fileManager.attributesOfItem(atPath: fileURL.path)[.size] as? Int,
      size > SessionLimits.maxScrollbackFileBytes
    {
      logger.notice("scrollback sidecar is \(size) bytes, over the limit — discarding")
      try? fileManager.removeItem(at: fileURL)
      return nil
    }
    guard let data = try? Data(contentsOf: fileURL) else { return nil }
    guard let text = String(data: data, encoding: .utf8) else {
      logger.notice("scrollback sidecar is not valid UTF-8 — discarding")
      try? fileManager.removeItem(at: fileURL)
      return nil
    }
    let cleaned = Self.strippingControlBytes(text)
    return cleaned.isEmpty ? nil : cleaned
  }

  /// Drop sidecars for panes that are no longer in the session.
  ///
  /// Runs once after the write pass, unconditionally — including when every write failed. A pane
  /// whose capture is now empty wrote no sidecar, so its old one is removed here and yesterday's
  /// output cannot reappear under today's empty pane.
  func pruneScrollback(keeping keys: Set<String>) {
    guard !isDisabled else { return }
    guard
      let entries = try? fileManager.contentsOfDirectory(
        at: scrollbackDirectory, includingPropertiesForKeys: nil)
    else { return }
    for entry in entries where entry.pathExtension == "txt" {
      let key = entry.deletingPathExtension().lastPathComponent
      if !keys.contains(key) { try? fileManager.removeItem(at: entry) }
    }
  }

  /// Remove C0 control bytes except newline, carriage return and tab.
  ///
  /// The captured text is rendered output, never raw PTY bytes, so it carries no escape sequences to
  /// begin with. This exists so a hand-edited sidecar cannot inject one and leave the parser
  /// mid-sequence on replay. CR is kept: the divider is CRLF.
  nonisolated static func strippingControlBytes(_ text: String) -> String {
    String(
      text.unicodeScalars.filter { scalar in
        scalar == "\n" || scalar == "\r" || scalar == "\t" || scalar.value >= 0x20
      })
  }

  @discardableResult
  private func persist(_ file: SessionFile) -> Bool {
    let encoder = JSONEncoder()
    encoder.dateEncodingStrategy = .iso8601
    // Readable and diff-stable on purpose: "delete this file and relaunch" is a support instruction
    // a user can follow, and the file is something a bug report can usefully attach.
    encoder.outputFormatting = [.prettyPrinted, .sortedKeys]

    guard let data = try? encoder.encode(file) else {
      logger.error("session snapshot could not be encoded")
      return false
    }
    do {
      // `Data.write(.atomic)` does NOT create intermediate directories, and the bundle-id
      // subdirectory does not exist on a first run — without this every write fails silently.
      try fileManager.createDirectory(
        at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
      // Atomic: a reader sees the complete old document or the complete new one, never a partial
      // write from a process that died mid-save.
      try data.write(to: url, options: .atomic)
      return true
    } catch {
      logger.error("session snapshot could not be written: \(error.localizedDescription)")
      return false
    }
  }

  /// Move a file this build cannot read aside — once. A prior quarantine is replaced rather than
  /// accumulating; the newest failure is the useful one.
  private func quarantine() {
    try? fileManager.removeItem(at: quarantineURL)
    do {
      try fileManager.moveItem(at: url, to: quarantineURL)
    } catch {
      // If it cannot even be moved, delete it — leaving it in place would fail the same way on
      // every launch forever.
      try? fileManager.removeItem(at: url)
    }
  }
}

import Foundation

/// Shared, app-wide project data: the project list plus everything derived from it that is
/// identical across windows — root branch/bookmark labels, the VCS/CI status cache, GitHub-CLI
/// availability, and the in-flight project busy set. Extracted from `AppStore` (issue #70) so that
/// multiple per-window `AppStore`s can share one project list while each keeps its own selection,
/// terminals, splits, history, and run state.
///
/// This first step is **storage-only and behaviour-preserving**: `AppStore` proxies these
/// properties straight through to here and re-publishes the store's `objectWillChange`, so the
/// single shared `AppStore` still behaves exactly as before. The CLI/load logic stays on `AppStore`
/// for now (it mutates these via the proxies); per-window construction and the multi-window wiring
/// land in a follow-up.
@MainActor
final class ProjectStore: ObservableObject {
  /// The shared instance used in production (every window's `AppStore` points at it). Tests
  /// construct an isolated `AppStore()`, which gets its own fresh `ProjectStore`, so they never
  /// pollute this singleton or each other.
  static let shared = ProjectStore()

  /// The list of configured projects (from the CLI's `~/.config/workroom/config.json`). The one
  /// piece of state shared across all windows.
  @Published var projects: [Project] = []

  /// Per-project resolved root branch/bookmark labels, hydrated asynchronously after each load.
  @Published var rootRefs: [Project.ID: RootRef] = [:]

  /// Per-workroom (and per-root) VCS + CI status driving the ambient badges and the Changes panel
  /// (issue #24), keyed by `SidebarID`. Resolved app-side, best-effort/"last checked". Shared so two
  /// windows showing the same workroom report a consistent badge and don't double the probes.
  @Published var workroomStatuses: [SidebarID: WorkroomStatus] = [:]

  /// Whether the GitHub CLI is usable for the PR/CI probes (machine-global). Optimistic default so
  /// no warning flashes before the first check.
  @Published var githubCLIStatus: GitHubCLIStatus = .available

  /// Owns the `gh auth status` probe: its freshness clock AND its single-flight, so N windows share
  /// one `gh` and the staleness check can't interleave with the write the way a bare timestamp on
  /// this class did. `githubCLIStatus` above is the SwiftUI-observable mirror of what it decided.
  ///
  /// A `var` purely so tests can swap in an instance with millisecond TTLs; production never
  /// reassigns it.
  var ghAuthCache = GitHubAuthCache()

  /// Project paths with an in-flight create/delete (for per-row progress + disabling).
  @Published var busyProjects: Set<String> = []

  /// Target ids of workrooms whose create is still in flight — from the "created" event until the
  /// create flow ends (issue #116). A workroom here must not be deleted: its setup script is running
  /// against the worktree. Shared across windows so a delete from ANY window is blocked, not just the
  /// creating one.
  @Published var creatingWorkrooms: Set<TerminalTarget.ID> = []

  /// Sidebar rows with a commit in flight, for the per-row button state.
  ///
  /// Shared across windows for the reason `creatingWorkrooms` is: `AppStore` is per WINDOW, but
  /// `JJSnapshotGate` and the `index.lock` contention it exists to prevent are per PROCESS. Held on
  /// the window's own store, a second window's 15s sweep, FSEvents lane and Refresh button all saw an
  /// empty set and kept probing a repo mid-write.
  @Published var committingTargets: Set<SidebarID> = []

  /// How many commits are in flight against each project root, which is what the read lanes actually
  /// have to stand clear of.
  ///
  /// Keyed by project root, not by row: the gate serializes on the project root, and a git worktree's
  /// index and refs live in the MAIN repo — so a commit in workroom A contends with a status probe of
  /// workroom B of the same project, which a per-row check waved straight through. Counted rather than
  /// a `Set` because the app's premise is N parallel workrooms, so two of one project can legitimately
  /// commit at once and the first to finish must not clear the other's suppression.
  @Published var committingProjectRoots: [String: Int] = [:]

  /// Target ids of workrooms with an in-flight optimistic deletion — dropped from the sidebar but
  /// their teardown (worktree/config removal) not yet finished. `AppStore.apply` filters these out of
  /// every incoming CLI `list`, so a stale snapshot taken before the teardown persisted can't
  /// resurrect a just-deleted workroom (the create/delete reload race). Cleared when teardown ends.
  @Published var deletingWorkrooms: Set<TerminalTarget.ID> = []

  /// Whether the persisted last-session selection is still up for grabs (issue #70). The first
  /// window to launch with `restore == true` consumes it and restores the saved selection; every
  /// other window — including every ⌘N window — gets `false` and so starts blank.
  private var pendingInitialRestore = true

  /// Claim the one-time launch restore. Returns true exactly once (for the first restoring window).
  func consumeInitialRestore() -> Bool {
    defer { pendingInitialRestore = false }
    return pendingInitialRestore
  }

  // MARK: Saved session (issue #46)

  /// Windows from the saved session that no window has adopted yet. Loaded once, lazily, by the first
  /// claim — which is also the moment saves are suspended, so a restoring window cannot overwrite the
  /// file before the rest of it has been claimed.
  private var unclaimedSessionWindows: [WindowSession] = []
  private var didLoadSession = false
  /// Injectable so tests drive a temp session file instead of the developer's real one.
  var sessionCoordinator: SessionCoordinator = .shared
  /// True between loading the session and finishing the restore, so the suspend/resume is balanced
  /// exactly once however many windows take part.
  private var isRestoringSession = false

  /// Sessions already handed to a window, by the key that window now owns. Makes claiming idempotent:
  /// `WindowAccessor` can resolve the same window more than once, and a repeat claim must return the
  /// same session rather than consume a second one.
  private var claimedSessions: [UUID: WindowSession] = [:]
  /// Keys handed to `openWindow` whose window has not claimed yet. Dispatched once so a `.task`
  /// re-fire cannot open a second copy of the same window.
  private var dispatchedSessionKeys: Set<UUID> = []
  /// How many windows have claimed a session and not yet finished restoring it. Saving resumes when
  /// this reaches zero AND nothing is still awaiting a window.
  private var outstandingRestores = 0
  /// The key of the window that was key at the last quit, so focus lands where the user left it once
  /// every window is back.
  private var keyWindowSessionKey: UUID?

  /// Adopt a saved window for this store, or nil when there is nothing to adopt.
  ///
  /// Loading is lazy so the read happens at the first claim rather than at app init — the claim is
  /// made from `AppStore.attachWindow`, when a real `NSWindow` exists but before it is shown, which is
  /// both early enough for the frame and late enough that a speculative SwiftUI view init cannot
  /// consume a session no window ever uses.
  ///
  /// The launch window adopts the first unclaimed session (its own seed id is freshly minted, so it
  /// cannot match anything on disk) and takes that session's key as its own. A sibling was opened FOR
  /// a specific key and claims exactly that one — never another window's.
  func claimSession(for key: UUID, isLaunchWindow: Bool) -> WindowSession? {
    loadSessionIfNeeded()
    if let already = claimedSessions[key] { return already }

    let claimed: WindowSession?
    if isLaunchWindow {
      claimed = unclaimedSessionWindows.isEmpty ? nil : unclaimedSessionWindows.removeFirst()
    } else if let index = unclaimedSessionWindows.firstIndex(
      where: { $0.windowKey == key.uuidString })
    {
      claimed = unclaimedSessionWindows.remove(at: index)
    } else {
      claimed = nil
    }

    guard let claimed else { return nil }
    let ownedKey = UUID(uuidString: claimed.windowKey) ?? key
    claimedSessions[ownedKey] = claimed
    dispatchedSessionKeys.remove(ownedKey)
    outstandingRestores += 1
    if claimed.isKey { keyWindowSessionKey = ownedKey }
    return claimed
  }

  /// Keys of saved windows nobody has claimed yet, marked as dispatched so they are handed out once.
  /// The launch window opens one window per key.
  func pendingSessionKeys() -> [UUID] {
    loadSessionIfNeeded()
    let keys = unclaimedSessionWindows.compactMap { UUID(uuidString: $0.windowKey) }
      .filter { !dispatchedSessionKeys.contains($0) }
    dispatchedSessionKeys.formUnion(keys)
    return keys
  }

  /// One window finished restoring. Saving resumes only once every window has, so a half-restored
  /// document is never written over a full one.
  ///
  /// The `unclaimedSessionWindows` check is load-bearing, not belt and braces: the launch window
  /// finishes its own restore INSIDE `bootstrap`, which returns before `pendingSessionKeys` has handed
  /// anything out. Ending the restore on "nothing outstanding, nothing dispatched" alone would
  /// therefore fire while the siblings were still only on disk — clearing them, so the fan-out found
  /// nothing to open and only one window ever came back.
  func finishSessionRestore() {
    guard isRestoringSession else { return }
    outstandingRestores = max(0, outstandingRestores - 1)
    guard outstandingRestores == 0, dispatchedSessionKeys.isEmpty,
      unclaimedSessionWindows.isEmpty
    else { return }
    endSessionRestore()
  }

  /// Bring the window that was key at the last quit back to the front, then resume saving.
  ///
  /// `timedOut` is the watchdog calling, and it changes the ending: see below.
  private func endSessionRestore(timedOut: Bool = false) {
    guard isRestoringSession else { return }
    // **A restore that never finished must not resume saving.** `AppStore.load` swallows a CLI
    // failure and returns WITHOUT calling `apply`, so `restorePersistedSessionIfPending` never runs
    // and this window's restore stays outstanding forever. Resuming here would then rebuild the
    // document from a window holding nothing and overwrite the file — one `workroom list` timing out
    // on a cold machine would silently destroy the user's whole saved session, ~16 seconds into a
    // launch that was supposed to bring it back. Freezing keeps the file intact for the next launch.
    let incomplete = outstandingRestores > 0 || !unclaimedSessionWindows.isEmpty
    isRestoringSession = false
    unclaimedSessionWindows.removeAll()
    dispatchedSessionKeys.removeAll()
    claimedSessions.removeAll()
    keyWindowSessionKey = timedOut && incomplete ? nil : keyWindowSessionKey
    if timedOut && incomplete {
      sessionCoordinator.freezeWithoutWriting()
      return
    }
    if let keyWindowSessionKey,
      let store = WindowRegistry.shared.allStores.first(where: {
        $0.sessionKey == keyWindowSessionKey
      })
    {
      store.hostWindow?.makeKeyAndOrderFront(nil)
    }
    keyWindowSessionKey = nil
    sessionCoordinator.resumeSaves()
  }

  private func loadSessionIfNeeded() {
    guard !didLoadSession else { return }
    didLoadSession = true
    guard case .restored(let file, _) = sessionCoordinator.read() else { return }
    unclaimedSessionWindows = file.windows
    isRestoringSession = true
    // Suspended until `finishSessionRestore`. Without this the first window's restore marks the
    // session dirty, and that write would rebuild the document from the windows that exist SO FAR —
    // overwriting the file and discarding the ones still to be claimed.
    sessionCoordinator.suspendSaves()
    // Watchdog: a dispatched window that never opens (a scene SwiftUI declines to create, a window
    // closed mid-restore) would otherwise leave saving suspended for the whole run — the app would
    // silently stop persisting anything. Restoring is a launch-time operation measured in
    // milliseconds, so anything still outstanding this much later is not coming.
    DispatchQueue.main.asyncAfter(deadline: .now() + sessionRestoreTimeout) { [weak self] in
      MainActor.assumeIsolated { self?.endSessionRestore(timedOut: true) }
    }
  }

  /// How long to wait for every dispatched window before giving up. Instance-level so a test can
  /// shorten it and exercise the real watchdog rather than a stand-in for it.
  var sessionRestoreTimeout: TimeInterval = ProjectStore.defaultSessionRestoreTimeout
  static let defaultSessionRestoreTimeout: TimeInterval = 15
}

import AppKit
import Foundation
import OSLog

/// Decides *when* the saved session is written (issue #46). `SessionStore` owns the file;
/// `AppStore+Session` owns what one window contributes; this owns coalescing, the restore gate, and
/// the quit freeze.
///
/// There is exactly one writer, and it rebuilds the whole document from every live window. That
/// replaces `AppStore.persistsSidebarPrefs` arbitration *for the session only*: that gate exists
/// because a single `Defaults` key cannot hold N windows — this file can. `persistsSidebarPrefs`
/// still governs the Defaults keys it always did.
@MainActor
final class SessionCoordinator {
  static let shared = SessionCoordinator(store: .forCurrentEnvironment())

  /// Coalescing window. Long enough that a burst of layout edits costs one write.
  static let defaultDebounce: TimeInterval = 1
  /// **The ceiling is not an optimisation — it is what makes saving work at all.**
  ///
  /// The dirty sources publish faster than 1 Hz whenever a terminal is doing anything:
  /// `TerminalSessions.pulsePaneActivity` bumps a `@Published` dict per activity report, and every
  /// live-title/cwd/progress update reassigns `tabsByTarget` (`TerminalTab` is a value type). A plain
  /// cancel-and-replace debounce therefore has its deadline pushed out forever while output streams,
  /// and **never fires** — so splitting a pane beside a running dev server would never be saved.
  ///
  /// Recording when the session FIRST went dirty and forcing a write once this much time has passed
  /// bounds the loss regardless of how chatty the terminals are.
  static let defaultCeiling: TimeInterval = 5

  private let store: SessionStore
  private let debounce: TimeInterval
  private let ceiling: TimeInterval
  private let capture: () -> [WindowSession]
  /// Writes each live pane's scrollback into the store (issue #144). Separate from `capture` because
  /// it runs ONLY at quit: reading every pane's history is far too heavy for a coalesced save.
  private let captureScrollback: (SessionStore) -> Void
  private let logger = Logger(
    subsystem: "com.developwithstyle.workroom", category: "session")

  private var pending: DispatchWorkItem?
  /// When the current dirty streak began — the ceiling is measured from here, not from the last edit.
  private var dirtySince: Date?
  /// The last document written, compared with `==` rather than a hash: Swift seeds `hashValue` per
  /// process, and a collision would silently suppress a write the user needs.
  private var lastWritten: [WindowSession]?
  /// What the last **successful** write persisted, or nil when nothing has landed yet. Exposed so a
  /// test can assert that a failed write is not latched as written.
  var lastWrittenWindows: [WindowSession]? { lastWritten }
  /// Depth rather than a flag so nested suspensions (several windows restoring) cannot resume early.
  private var suspensions = 0
  private var dirtyWhileSuspended = false
  /// Set once the app is genuinely terminating. Windows close one by one during a quit, and the
  /// document is rebuilt from the LIVE windows — without this, the last window closing would
  /// overwrite a good session with an empty one after the flush already wrote it.
  private(set) var isFrozen = false

  init(
    store: SessionStore = SessionStore(),
    debounce: TimeInterval = SessionCoordinator.defaultDebounce,
    ceiling: TimeInterval = SessionCoordinator.defaultCeiling,
    capture: (() -> [WindowSession])? = nil,
    captureScrollback: ((SessionStore) -> Void)? = nil
  ) {
    self.store = store
    self.debounce = debounce
    self.ceiling = ceiling
    self.capture = capture ?? { WindowRegistry.shared.captureSessionWindows() }
    self.captureScrollback =
      captureScrollback ?? { store in
        for appStore in WindowRegistry.shared.allStores { appStore.captureScrollback(into: store) }
      }
  }

  /// Exposed so a caller can tell "no session" from "a session this build must not touch".
  var writesDisabled: Bool { store.writesDisabled }

  // MARK: Restore gate

  /// True while a restore is in flight, so nothing writes a half-restored document.
  var isSuspended: Bool { suspensions > 0 }

  /// Stop writing until the matching `resumeSaves()`.
  ///
  /// **This is the gate that stops the launch window deleting the others.** Restoring window 1
  /// mutates `TerminalSessions` and `AppStore`, which marks the session dirty. If that write landed
  /// before the sibling windows had opened and registered, the document would be rebuilt from the one
  /// live window and overwrite the file — silently discarding windows 2 and 3 on the very launch that
  /// was meant to bring them back.
  func suspendSaves() {
    suspensions += 1
    pending?.cancel()
    pending = nil
  }

  func resumeSaves() {
    guard suspensions > 0 else { return }
    suspensions -= 1
    guard suspensions == 0, dirtyWhileSuspended else { return }
    dirtyWhileSuspended = false
    markDirty()
  }

  // MARK: Dirty tracking

  /// The session changed. Safe to call at any rate — this is called from publishers that fire many
  /// times a second.
  func markDirty() {
    guard !isFrozen, !store.writesDisabled else { return }
    guard !isSuspended else {
      dirtyWhileSuspended = true
      return
    }

    let now = Date()
    let start = dirtySince ?? now
    dirtySince = start

    // Past the ceiling, write on the next turn rather than pushing the deadline out again.
    //
    // Scheduled at zero delay rather than called inline, because the loudest dirty source is
    // `terminals.objectWillChange`, which fires BEFORE the mutation lands: capturing inline would
    // snapshot the state the change was about to replace. Zero delay keeps the ceiling's guarantee
    // (this run loop turn) while letting the mutation complete first.
    pending?.cancel()
    let work = DispatchWorkItem { [weak self] in
      MainActor.assumeIsolated { self?.writeIfChanged() }
    }
    pending = work
    let delay = now.timeIntervalSince(start) >= ceiling ? 0 : debounce
    DispatchQueue.main.asyncAfter(deadline: .now() + delay, execute: work)
  }

  /// Capture and persist immediately if anything actually changed. Also the ceiling's landing point.
  func writeIfChanged() {
    pending?.cancel()
    pending = nil
    dirtySince = nil
    guard !isFrozen, !store.writesDisabled, !isSuspended else { return }

    let windows = capture()
    guard windows != lastWritten else { return }
    lastWritten = windows
    // `lastWritten` is the gate that drops an unchanged save, so a write that FAILED must not be
    // remembered as written: after a disk-full or permissions blip, every later attempt at the same
    // state would be suppressed and the user's layout would silently stop being saved until they
    // changed something else. Clearing it on failure makes the next dirty mark retry.
    store.write(makeFile(windows)) { [weak self] didWrite in
      guard let self, !didWrite, self.lastWritten == windows else { return }
      self.lastWritten = nil
    }
  }

  // MARK: Quit

  /// Capture and write **synchronously**, then stop writing for the rest of the process.
  ///
  /// Called past the quit confirmation — never above it. A cancelled ⌘Q must leave saving fully
  /// working, so this cannot run anywhere a user can still say "no".
  func flushAndFreeze() {
    guard !isFrozen else { return }
    pending?.cancel()
    pending = nil
    dirtySince = nil
    // Suspended means a restore never finished; the live windows are not the user's session, so
    // writing them now would replace a good file with a partial one.
    if !store.writesDisabled && !isSuspended {
      let windows = capture()
      lastWritten = windows
      store.writeSynchronously(makeFile(windows))
      // Scrollback is captured HERE and nowhere else (issue #144): quitting is the one moment worth
      // reading every pane's history for. Prune afterwards, unconditionally, so a pane that captured
      // nothing this time loses its old sidecar rather than restoring yesterday's output.
      captureScrollback(store)
      store.pruneScrollback(keeping: Self.tabKeys(in: windows))
    }
    isFrozen = true
  }

  /// Stop writing for the rest of the run **without** writing anything.
  ///
  /// The abandoned-restore path. If a window claimed a saved session and never restored it — a `list`
  /// that threw, a scene SwiftUI declined to create — then the live windows are NOT the user's
  /// session, and resuming saves would rebuild the document from those empty windows and overwrite a
  /// perfectly good file. Freezing instead preserves it, so the next launch can still restore.
  ///
  /// This costs the current run's layout changes, which is the right trade: the file on disk is real
  /// work the user did, and what would replace it is the wreckage of a failed launch.
  func freezeWithoutWriting() {
    guard !isFrozen else { return }
    pending?.cancel()
    pending = nil
    dirtySince = nil
    isFrozen = true
    logger.notice("session restore did not complete — writes frozen to preserve the saved session")
  }

  // MARK: Read

  func read() -> SessionStore.ReadOutcome { store.read() }

  /// A restored pane's saved text, for replay (issue #144).
  func scrollback(forTabKey key: String) -> String? { store.readScrollback(forTabKey: key) }

  /// Every tab key in the document, which is exactly the set of sidecars worth keeping.
  private static func tabKeys(in windows: [WindowSession]) -> Set<String> {
    Set(windows.flatMap { $0.targets.flatMap { $0.tabs.map(\.key) } })
  }

  private func makeFile(_ windows: [WindowSession]) -> SessionFile {
    SessionFile(
      savedAt: Date(),
      appVersion: Bundle.main.object(forInfoDictionaryKey: "CFBundleShortVersionString") as? String,
      windows: windows)
  }
}

extension WindowRegistry {
  /// Every live window's contribution to the saved session, in a stable order so an unchanged layout
  /// produces an unchanged document (and therefore no write).
  func captureSessionWindows() -> [WindowSession] {
    allStores
      .sorted { $0.windowNumber < $1.windowNumber }
      .map { $0.captureWindowSession() }
  }
}

import Foundation

/// The on-disk shape of a saved session — the open panels, split layouts, and windows restored on
/// the next launch (issue #46). Written by `SessionStore` to
/// `Application Support/Workroom/<bundle id>/session.json`.
///
/// **Every type here is a hand-written mirror.** No runtime type (`PaneLayout`, `TerminalTab`,
/// `SidebarID`, the content descriptors) gains `Codable`, so the file format is never hostage to an
/// internal field rename — the same stored-data-contract rule `RunConfig` carries in
/// `DefaultsKeys.swift`. The field names below ARE the contract; renaming one silently invalidates
/// every user's saved session.
///
/// # Versioning rule — read before bumping `schemaVersion`
///
/// **Additive changes NEVER bump `schemaVersion`.** Adding a tab kind, or adding an optional field,
/// is additive. Only a breaking reshape bumps.
///
/// This is what makes the lossy decoding below load-bearing rather than decorative: a Nightly build
/// writes a fifth tab kind, the user rolls back to stable, and stable drops that one tab while
/// restoring everything else. Bump the version for an additive kind and the whole file is discarded
/// before the lossy path ever runs — deleting every user's session for no reason.
///
/// The same split the app already draws between versioning a key (`inspector.layout.v2`) and
/// reconciling a shape (`AppStore.reconcileInspectorState`): version to discard, reconcile to keep.
///
/// A **newer** `schemaVersion` is read-only: restore nothing AND write nothing for that run, or an
/// older build silently destroys a newer one's session on its next save. Three build identities ship
/// side by side (Workroom, Workroom Dev, Workroom Nightly), so that rollback is a real path.
///
/// # What is deliberately absent
///
/// - **The PTY and child processes.** A restored terminal is a fresh login shell in the remembered
///   directory; the process it was running is gone. (Its *text* does come back — scrollback lives in
///   sidecar files beside this document, never inside it. See `SessionStore` and issue #144.)
/// - **Run tabs.** Restoring one would resurrect a dev server with no `AppStore.RunState` behind it —
///   an untracked process orphaned on its port, the failure `WindowRegistry.runOwner(for:excluding:)`
///   and issue #7 exist to prevent. `Defaults[.runCommands]` already survives, and `RunConfig.autoRun`
///   is the deliberate opt-in.
/// - **`liveTitle` / `progressActive` / activity pulses.** Display state about a process that no
///   longer exists. Excluding them is also what keeps the save digest stable: a terminal animating
///   its title produces a byte-identical snapshot, so it costs a comparison and no disk write.
/// - **Navigation history.** Its entries key on tab ids, which restore re-mints by design.

// MARK: - Limits

/// Bounds on what a session file may ask the app to allocate at launch. These are a real ceiling,
/// not decoration: restore materialises every target's tab models eagerly (the sidebar's terminal
/// subtree renders from them), so a hostile or corrupt file could otherwise allocate tens of
/// thousands of views before the first frame. Anything dropped is logged — silent truncation reads
/// as full coverage.
enum SessionLimits {
  static let maxWindows = 8
  /// Workroom's whole point is managing many workrooms, so this has to sit above real usage rather
  /// than above a guess: 20 was tight enough that a heavy user would silently lose targets on every
  /// relaunch. **Enforced at capture as well as at read** (`AppStore.captureWindowSession`), so the
  /// app can never author a file it will later truncate.
  static let maxTargetsPerWindow = 40
  static let maxTabsPerTarget = 20
  /// Split trees are user-built by repeated ⌘D; a dozen levels is far past any real layout, and the
  /// cap is what stops a hand-edited file recursing `materialize` into the stack.
  static let maxSplitDepth = 12
  /// Nesting depth refused **during decoding**, before a tree is built at all.
  ///
  /// `maxSplitDepth` is checked by `sanitized()`, which runs only once a `LayoutNode` already exists —
  /// far too late, because `init(from:)` recurses per level as it decodes. A deeply nested file would
  /// overflow the stack, and a crash (unlike a thrown error) is never quarantined, so the app would
  /// crash on every launch with no way out. Throwing here drops one element through `@Lossy` instead.
  /// Well above `maxSplitDepth` plus the outer document's own coding path, so no real file trips it.
  static let maxDecodeDepth = 64
  /// Refused before decoding — array caps bound element *counts*, not the size of one giant string.
  ///
  /// Generous rather than tight: this is a quarantine trigger, and a false positive costs the user
  /// their whole session. The element caps above are what actually bound the work.
  static let maxFileBytes = 4 * 1024 * 1024
  /// Clamps paths, titles, and commit ids individually.
  static let maxStringLength = 4096
  /// Per-pane scrollback kept in a sidecar file (issue #144). The value is overwhelmingly at the
  /// recent end, and a cap keeps the quit path bounded no matter how much a pane logged.
  static let maxScrollbackBytes = 256 * 1024
  /// A sidecar larger than this on disk is corrupt by definition — twice the cap, so a legitimate
  /// file can never trip it.
  static let maxScrollbackFileBytes = 512 * 1024
}

// MARK: - Lossy array decoding

/// An array that drops the elements it cannot decode instead of failing the whole document.
///
/// This is the single most valuable primitive in the schema: it turns "a newer build wrote a tab kind
/// this build has never heard of" from *your entire session is gone* into *one tab is missing*. It
/// only pays because additive changes do not bump `schemaVersion` (see the file header) — otherwise
/// the envelope check discards the file before any element is examined.
@propertyWrapper
struct Lossy<Element: Codable & Sendable>: Codable, Sendable {
  var wrappedValue: [Element]

  init(wrappedValue: [Element]) { self.wrappedValue = wrappedValue }

  /// Consumes exactly one element of any shape. Decoding a *failed* element does not advance an
  /// `UnkeyedDecodingContainer`, so a permissive type has to consume it or the loop never progresses.
  private struct AnyElement: Decodable {
    init(from decoder: Decoder) throws { _ = decoder }
  }

  init(from decoder: Decoder) throws {
    var container = try decoder.unkeyedContainer()
    var decoded: [Element] = []
    while !container.isAtEnd {
      let indexBefore = container.currentIndex
      do {
        decoded.append(try container.decode(Element.self))
      } catch {
        _ = try? container.decode(AnyElement.self)
      }
      // Belt and braces: if neither the decode nor the skip advanced the cursor, stop rather than
      // spin forever on a container shape we did not anticipate.
      if container.currentIndex == indexBefore { break }
    }
    wrappedValue = decoded
  }

  func encode(to encoder: Encoder) throws {
    var container = encoder.unkeyedContainer()
    for element in wrappedValue { try container.encode(element) }
  }
}

extension Lossy: Equatable where Element: Equatable {}
extension Lossy: Hashable where Element: Hashable {}

extension KeyedDecodingContainer {
  /// Makes an absent lossy array decode to empty rather than throwing, so a field added in a later
  /// version is readable by a build that predates it.
  func decode<T>(_ type: Lossy<T>.Type, forKey key: Key) throws -> Lossy<T> {
    try decodeIfPresent(type, forKey: key) ?? Lossy(wrappedValue: [])
  }
}

// MARK: - Layout tree

/// The Codable mirror of `PaneLayout`, generic over its leaf address (a tab key, or a target-id
/// string for the workroom split). Hand-written with an explicit `kind` discriminator so the on-disk
/// format is a contract THIS file owns, not whatever Swift synthesises for an indirect enum with
/// associated values.
///
/// `PaneLayout`'s per-split `UUID` is deliberately NOT persisted: it addresses a divider during a
/// drag and nothing refers to it across a launch. `materialize` mints a fresh one.
indirect enum LayoutNode<Leaf: Codable & Hashable & Sendable>: Codable, Hashable, Sendable {
  case leaf(Leaf)
  case split(orientation: String, ratio: Double, first: LayoutNode, second: LayoutNode)

  static var horizontal: String { "horizontal" }
  static var vertical: String { "vertical" }

  private enum CodingKeys: String, CodingKey {
    case kind, leaf, orientation, ratio, first, second
  }
  private enum Kind: String, Codable {
    case leaf, split
  }

  init(from decoder: Decoder) throws {
    // Refused BEFORE recursing. `sanitized()`'s `maxSplitDepth` check cannot help here — it inspects
    // a tree that decoding has already built, and building it is the stack hazard. Each nesting level
    // adds a `first`/`second` key to the coding path, so the path length is the live depth.
    guard decoder.codingPath.count <= SessionLimits.maxDecodeDepth else {
      throw DecodingError.dataCorrupted(
        DecodingError.Context(
          codingPath: decoder.codingPath,
          debugDescription: "split tree nested deeper than \(SessionLimits.maxDecodeDepth)"))
    }
    let container = try decoder.container(keyedBy: CodingKeys.self)
    switch try container.decode(Kind.self, forKey: .kind) {
    case .leaf:
      self = .leaf(try container.decode(Leaf.self, forKey: .leaf))
    case .split:
      self = .split(
        orientation: try container.decode(String.self, forKey: .orientation),
        ratio: try container.decode(Double.self, forKey: .ratio),
        first: try container.decode(LayoutNode.self, forKey: .first),
        second: try container.decode(LayoutNode.self, forKey: .second))
    }
  }

  func encode(to encoder: Encoder) throws {
    var container = encoder.container(keyedBy: CodingKeys.self)
    switch self {
    case .leaf(let leaf):
      try container.encode(Kind.leaf, forKey: .kind)
      try container.encode(leaf, forKey: .leaf)
    case .split(let orientation, let ratio, let first, let second):
      try container.encode(Kind.split, forKey: .kind)
      try container.encode(orientation, forKey: .orientation)
      try container.encode(ratio, forKey: .ratio)
      try container.encode(first, forKey: .first)
      try container.encode(second, forKey: .second)
    }
  }

  /// Every leaf address in reading order — the counterpart of `PaneLayout.tabIDs`, used to validate
  /// a decoded tree against the tabs that actually survived.
  var leaves: [Leaf] {
    switch self {
    case .leaf(let leaf): return [leaf]
    case .split(_, _, let first, let second): return first.leaves + second.leaves
    }
  }

  /// Depth of the deepest split, so a hand-edited tree can be rejected before `materialize` walks it.
  var depth: Int {
    switch self {
    case .leaf: return 1
    case .split(_, _, let first, let second): return 1 + max(first.depth, second.depth)
    }
  }
}

extension LayoutNode {
  /// Runtime tree → snapshot tree. `address` maps a runtime leaf to its persisted key; a leaf that
  /// maps to nil is dropped and its parent collapses to the surviving sibling — the same collapse
  /// rule as `PaneLayout.removingLeaf`.
  ///
  /// Returns nil when fewer than two leaves survive, mirroring `materialize`: a lone leaf is not a
  /// split, and writing one would put a shape in the file that the live model cannot hold. Excluding
  /// a run tab from a two-pane split is exactly this case.
  static func capture<L: Hashable>(
    _ layout: PaneLayout<L>, address: (L) -> Leaf?
  ) -> LayoutNode? {
    guard let tree = captureNode(layout, address: address) else { return nil }
    guard case .split = tree else { return nil }
    return tree
  }

  private static func captureNode<L: Hashable>(
    _ layout: PaneLayout<L>, address: (L) -> Leaf?
  ) -> LayoutNode? {
    switch layout {
    case .leaf(let id):
      return address(id).map { .leaf($0) }
    case .split(_, let orientation, let ratio, let first, let second):
      let capturedFirst = captureNode(first, address: address)
      let capturedSecond = captureNode(second, address: address)
      switch (capturedFirst, capturedSecond) {
      case (let first?, let second?):
        return .split(
          orientation: orientation == .horizontal ? horizontal : vertical,
          ratio: Double(ratio), first: first, second: second)
      // A split with one surviving child is not a split — it IS that child (`PaneLayout`'s
      // "a lone leaf is not a split" invariant, enforced at the boundary rather than left to callers).
      case (let only?, nil), (nil, let only?):
        return only
      case (nil, nil):
        return nil
      }
    }
  }

  /// Snapshot tree → runtime tree. `resolve` maps a persisted key to a live leaf; unresolvable leaves
  /// collapse into their sibling. Returns nil when fewer than two leaves survive, so a caller can
  /// never be handed a one-leaf "split".
  func materialize<L: Hashable>(_ resolve: (Leaf) -> L?) -> PaneLayout<L>? {
    guard let tree = materializeNode(resolve, depth: 0) else { return nil }
    guard case .split = tree else { return nil }
    return tree
  }

  private func materializeNode<L: Hashable>(
    _ resolve: (Leaf) -> L?, depth: Int
  ) -> PaneLayout<L>? {
    guard depth < SessionLimits.maxSplitDepth else { return nil }
    switch self {
    case .leaf(let key):
      return resolve(key).map { .leaf($0) }
    case .split(let orientation, let ratio, let first, let second):
      guard let resolvedOrientation = Self.orientation(from: orientation) else { return nil }
      let resolvedFirst = first.materializeNode(resolve, depth: depth + 1)
      let resolvedSecond = second.materializeNode(resolve, depth: depth + 1)
      switch (resolvedFirst, resolvedSecond) {
      case (let first?, let second?):
        return .split(
          id: UUID(), orientation: resolvedOrientation,
          ratio: PaneRatio.sanitize(CGFloat(ratio)), first: first, second: second)
      case (let only?, nil), (nil, let only?):
        return only
      case (nil, nil):
        return nil
      }
    }
  }

  /// An unrecognised orientation rejects the split (its tabs survive as solo panes) rather than
  /// guessing a layout the user never chose.
  private static func orientation(from raw: String) -> SplitOrientation? {
    switch raw {
    case horizontal: return .horizontal
    case vertical: return .vertical
    default: return nil
    }
  }
}

// MARK: - Tab payloads

/// A restored terminal: a fresh login shell in the remembered directory, titled as it was.
struct TerminalPayload: Codable, Hashable, Sendable {
  /// The stable "Terminal N" title, never the live OSC title — that describes a dead process.
  var defaultTitle: String
  /// The LAST REPORTED working directory, which is the whole value of restoring a terminal (not the
  /// directory the tab was originally opened at). Falls back to the target path when it no longer
  /// exists, since libghostty cannot spawn into a missing directory.
  var cwd: String?
}

/// `DiffSource` on disk. Split into a kind plus an optional commit id so a new case is an additive
/// change (unknown kind ⇒ that one tab drops) rather than a reshape.
struct DiffSourcePayload: Codable, Hashable, Sendable {
  var kind: String
  var commit: String?

  static let gitWorktree = "gitWorktree"
  static let jjWorkingCopy = "jjWorkingCopy"
  static let jjParent = "jjParent"
  static let commitKind = "commit"

  /// Exhaustive on purpose — a fifth `DiffSource` case must be a compile error here, not a tab that
  /// silently stops persisting.
  init(_ source: DiffSource) {
    switch source {
    case .gitWorktree: self.init(kind: Self.gitWorktree, commit: nil)
    case .jjWorkingCopy: self.init(kind: Self.jjWorkingCopy, commit: nil)
    case .jjParent: self.init(kind: Self.jjParent, commit: nil)
    case .commit(let id): self.init(kind: Self.commitKind, commit: id)
    }
  }

  init(kind: String, commit: String?) {
    self.kind = kind
    self.commit = commit
  }

  var source: DiffSource? {
    switch kind {
    case Self.gitWorktree: return .gitWorktree
    case Self.jjWorkingCopy: return .jjWorkingCopy
    case Self.jjParent: return .jjParent
    case Self.commitKind: return commit.map { .commit($0) }
    default: return nil
    }
  }
}

struct DiffPayload: Codable, Hashable, Sendable {
  var path: String
  /// `ChangedFile.Change.rawValue`. Re-resolved by the status sweep after restore
  /// (`AppStore.refreshOpenDiffChangeKinds`), so a stale value self-heals.
  var change: String
  var source: DiffSourcePayload
  var isPreview: Bool
  /// `DiffViewMode.rawValue` — the per-tab unified/side-by-side override, nil to follow the global.
  var viewMode: String?
}

struct FilePayload: Codable, Hashable, Sendable {
  var path: String
  var isPreview: Bool
  /// The per-tab Markdown source/preview override, nil for the default (rendered).
  var markdownPreview: Bool?
}

struct ChangesetPayload: Codable, Hashable, Sendable {
  var commitID: String
  var title: String
  var isPreview: Bool
  /// The selected file within the commit.
  var selectedPath: String?
}

/// One pane. Flat with optional payloads rather than an enum-with-associated-values on purpose: an
/// unknown `kind`, or a kind missing its required payload, drops THAT tab and keeps its siblings,
/// where a synthesised enum decoder would throw and take the whole target with it.
struct TabSession: Codable, Hashable, Sendable {
  /// Unique within its `TargetSession`, and the address the split tree and `focusedKey` point at.
  ///
  /// This is a join key valid only inside one snapshot — **never a cross-launch identity**. Restore
  /// mints fresh `TerminalTab.ID`s, because a tab id is unique across *windows* at runtime and
  /// notification routing (`WindowRegistry.ownerOf(tabID:)`) depends on that.
  ///
  /// Tabs are keyed rather than index-addressed because lossy decoding drops elements: with indices,
  /// dropping tab 2 of 5 would silently re-point every later split leaf at the wrong pane. Do not
  /// "simplify" this back to indices.
  var key: String
  var kind: String
  var terminal: TerminalPayload?
  var diff: DiffPayload?
  var file: FilePayload?
  var changeset: ChangesetPayload?

  static let terminalKind = "terminal"
  static let diffKind = "diff"
  static let fileKind = "file"
  static let changesetKind = "changeset"

  /// Whether this tab carries the payload its kind requires. An unknown kind, or a `.diff` with no
  /// diff payload, is dropped at materialise.
  var isWellFormed: Bool {
    switch kind {
    case Self.terminalKind: return terminal != nil
    case Self.diffKind: return diff != nil
    case Self.fileKind: return file != nil
    case Self.changesetKind: return changeset != nil
    default: return false
    }
  }
}

// MARK: - Target, window, file

/// One terminal target's panes: its tabs in strip order, its split, and what was focused.
struct TargetSession: Codable, Hashable, Sendable {
  /// `TerminalTarget.ID` — "wr|<project>|<name>" or "root|<project>". The same encoding
  /// `Defaults[.sidebarSelection]` and `workroomTabOrder` already use, resolved back through
  /// `AppStore.sidebarID(forTargetID:in:)`, which drops ids that no longer exist.
  var targetID: String
  /// Strip order. The array IS the order — no second field to fall out of sync with it.
  @Lossy var tabs: [TabSession]
  /// Leaves are `TabSession.key`. Nil when the target has no split.
  var split: LayoutNode<String>?
  var focusedKey: String?
  /// `TerminalSessions.counts` — so the next ⌘T after restoring "Terminal 3" is "Terminal 4".
  var terminalCounter: Int?

  init(
    targetID: String, tabs: [TabSession], split: LayoutNode<String>? = nil,
    focusedKey: String? = nil, terminalCounter: Int? = nil
  ) {
    self.targetID = targetID
    self.tabs = tabs
    self.split = split
    self.focusedKey = focusedKey
    self.terminalCounter = terminalCounter
  }
}

/// One window's whole restorable state.
struct WindowSession: Codable, Hashable, Sendable {
  /// Cross-launch window identity — the `WindowSeed.id` a window claims and then keeps. Windows have
  /// no such identity natively: `WindowSeed.launch` mints a fresh UUID on every access.
  var windowKey: String
  /// `NSStringFromRect`. Authoritative over `Defaults[.mainWindowFrame]`, which only ever held one
  /// window's frame and is now the cold-start fallback. Clamped to a visible screen on restore.
  var frame: String?
  /// Whether this was the key window, so the user lands where they left off.
  var isKey: Bool
  /// `TerminalTarget.ID` of the selected workroom. Authoritative over `Defaults[.sidebarSelection]`,
  /// which is the single-slot cold-start fallback for a first launch with no session.
  var selectedTargetID: String?
  @Lossy var targets: [TargetSession]
  /// `AppStore.workroomSplits` — leaves are `TerminalTarget.ID` strings. Several disjoint groups can
  /// coexist; each needs two or more live leaves to survive.
  @Lossy var workroomSplits: [LayoutNode<String>]
  /// `AppStore.expandedTerminalTargets` — which sidebar terminal subtrees are open.
  var expandedTargets: [String]?

  init(
    windowKey: String, frame: String? = nil, isKey: Bool = false,
    selectedTargetID: String? = nil, targets: [TargetSession] = [],
    workroomSplits: [LayoutNode<String>] = [], expandedTargets: [String]? = nil
  ) {
    self.windowKey = windowKey
    self.frame = frame
    self.isKey = isKey
    self.selectedTargetID = selectedTargetID
    self.targets = targets
    self.workroomSplits = workroomSplits
    self.expandedTargets = expandedTargets
  }
}

/// The document `session.json` holds.
struct SessionFile: Codable, Sendable {
  static let currentSchemaVersion = 1

  var schemaVersion: Int
  var savedAt: Date
  /// Diagnostics only — never branched on. Read it in a bug report, not in code.
  var appVersion: String?
  @Lossy var windows: [WindowSession]

  init(
    schemaVersion: Int = SessionFile.currentSchemaVersion, savedAt: Date,
    appVersion: String? = nil, windows: [WindowSession]
  ) {
    self.schemaVersion = schemaVersion
    self.savedAt = savedAt
    self.appVersion = appVersion
    self.windows = windows
  }

  /// How a decoded file relates to what this build can do.
  enum Compatibility: Equatable {
    /// Readable and writable.
    case current
    /// Written by a newer build: restore nothing AND write nothing, or this build's next save
    /// destroys a session it could not understand.
    case newer
    /// Written by an older schema with no migration — discard.
    case unreadable
  }

  var compatibility: Compatibility {
    if schemaVersion == Self.currentSchemaVersion { return .current }
    return schemaVersion > Self.currentSchemaVersion ? .newer : .unreadable
  }
}

// MARK: - Structural validation

/// What `sanitized()` threw away, so the caller can log it. Caps and validation that drop work
/// silently read as full coverage — this is what stops that.
struct SessionSanitizeReport: Equatable {
  var droppedWindows = 0
  var droppedTargets = 0
  var droppedTabs = 0
  var droppedSplits = 0

  var isEmpty: Bool {
    droppedWindows == 0 && droppedTargets == 0 && droppedTabs == 0 && droppedSplits == 0
  }

  var summary: String {
    "windows: \(droppedWindows), targets: \(droppedTargets), tabs: \(droppedTabs), "
      + "splits: \(droppedSplits)"
  }
}

extension SessionFile {
  /// Enforce every structural invariant restore depends on, and report what that cost.
  ///
  /// Array caps bound element *counts*; they do nothing about a hostile or corrupt *shape*. The real
  /// hazard is duplicate keys: restore builds dictionaries from `windowKey` / `targetID` / tab `key`,
  /// so a duplicate would silently redirect a split leaf or the focus to the wrong pane — a
  /// wrong-content bug with no crash to point at. First occurrence wins; the rest are dropped.
  ///
  /// Pure and `nonisolated`, so it is unit-testable without an `AppStore`, a window, or a file —
  /// the shape `AppStore.reconcileInspectorState` established.
  func sanitized() -> (file: SessionFile, report: SessionSanitizeReport) {
    var report = SessionSanitizeReport()
    var seenWindowKeys = Set<String>()
    var windows: [WindowSession] = []

    for window in self.windows {
      guard windows.count < SessionLimits.maxWindows else {
        report.droppedWindows += 1
        continue
      }
      guard seenWindowKeys.insert(window.windowKey).inserted else {
        report.droppedWindows += 1
        continue
      }
      windows.append(window.sanitized(into: &report))
    }

    var sanitized = self
    sanitized.windows = windows
    return (sanitized, report)
  }
}

extension WindowSession {
  fileprivate func sanitized(into report: inout SessionSanitizeReport) -> WindowSession {
    var seenTargetIDs = Set<String>()
    var targets: [TargetSession] = []

    for target in self.targets {
      guard targets.count < SessionLimits.maxTargetsPerWindow else {
        report.droppedTargets += 1
        continue
      }
      guard seenTargetIDs.insert(target.targetID).inserted else {
        report.droppedTargets += 1
        continue
      }
      guard let sanitized = target.sanitized(into: &report) else {
        report.droppedTargets += 1
        continue
      }
      targets.append(sanitized)
    }

    // A workroom-split group needs two or more distinct leaves to be a group at all, and a tree
    // deeper than the cap is rejected whole rather than walked.
    var splits: [LayoutNode<String>] = []
    for split in workroomSplits {
      let leaves = split.leaves
      guard split.depth <= SessionLimits.maxSplitDepth, leaves.count >= 2,
        Set(leaves).count == leaves.count
      else {
        report.droppedSplits += 1
        continue
      }
      splits.append(split)
    }

    var window = self
    window.targets = targets
    window.workroomSplits = splits
    window.frame = frame.map { String($0.prefix(SessionLimits.maxStringLength)) }
    window.selectedTargetID = selectedTargetID.map {
      String($0.prefix(SessionLimits.maxStringLength))
    }
    window.expandedTargets = expandedTargets.map { expanded in
      Array(Set(expanded)).sorted().map { String($0.prefix(SessionLimits.maxStringLength)) }
    }
    return window
  }
}

extension TargetSession {
  /// Nil when nothing usable survives — never an empty target, which would make
  /// `TerminalSessions.ensureTab`'s "has this target been seeded?" check lie.
  fileprivate func sanitized(into report: inout SessionSanitizeReport) -> TargetSession? {
    var seenKeys = Set<String>()
    var tabs: [TabSession] = []
    var sawPreview = false

    for tab in self.tabs {
      guard tabs.count < SessionLimits.maxTabsPerTarget else {
        report.droppedTabs += 1
        continue
      }
      // Clamped BEFORE the uniqueness check, not after: two keys that differ only past
      // `maxStringLength` collapse to the same clamped key, and a duplicate key silently re-points a
      // split leaf or the focus at the wrong pane. Checking first would wave both through.
      var tab = tab.clamped()
      guard tab.isWellFormed, seenKeys.insert(tab.key).inserted else {
        report.droppedTabs += 1
        continue
      }
      // At most one preview tab per target (`TerminalSessions.previewTabID`). A hand-edited file
      // with two would give the target two italic chips and an ambiguous retarget slot; keep the
      // first and persist the rest.
      if tab.isPreview {
        if sawPreview {
          tab.clearPreview()
        } else {
          sawPreview = true
        }
      }
      tabs.append(tab)
    }

    guard !tabs.isEmpty else { return nil }

    let liveKeys = Set(tabs.map(\.key))
    var split = self.split
    if let candidate = split {
      let leaves = candidate.leaves
      let resolvable = leaves.filter { liveKeys.contains($0) }
      if candidate.depth > SessionLimits.maxSplitDepth || Set(leaves).count != leaves.count
        || resolvable.count < 2
      {
        // The split does not survive, but its tabs do — they simply render as solo panes.
        report.droppedSplits += 1
        split = nil
      }
    }

    var target = self
    target.tabs = tabs
    target.split = split
    target.focusedKey = focusedKey.flatMap { liveKeys.contains($0) ? $0 : nil }
    target.targetID = String(targetID.prefix(SessionLimits.maxStringLength))
    return target
  }
}

extension TabSession {
  /// A preview flag is not identity, so clearing it keeps the tab rather than dropping it.
  fileprivate var isPreview: Bool {
    diff?.isPreview ?? file?.isPreview ?? changeset?.isPreview ?? false
  }

  fileprivate mutating func clearPreview() {
    diff?.isPreview = false
    file?.isPreview = false
    changeset?.isPreview = false
  }

  /// Clamp every free-form string. One giant path in an otherwise sane file is exactly what the
  /// element caps cannot catch.
  fileprivate func clamped() -> TabSession {
    func clamp(_ value: String) -> String { String(value.prefix(SessionLimits.maxStringLength)) }
    func clamp(_ value: String?) -> String? { value.map(clamp) }

    var tab = self
    tab.key = clamp(key)
    tab.kind = clamp(kind)
    if var terminal = tab.terminal {
      terminal.defaultTitle = clamp(terminal.defaultTitle)
      terminal.cwd = clamp(terminal.cwd)
      tab.terminal = terminal
    }
    if var diff = tab.diff {
      diff.path = clamp(diff.path)
      diff.source.commit = clamp(diff.source.commit)
      tab.diff = diff
    }
    if var file = tab.file {
      file.path = clamp(file.path)
      tab.file = file
    }
    if var changeset = tab.changeset {
      changeset.commitID = clamp(changeset.commitID)
      changeset.title = clamp(changeset.title)
      changeset.selectedPath = clamp(changeset.selectedPath)
      tab.changeset = changeset
    }
    return tab
  }
}

import AppKit
import Defaults
import Foundation
import OSLog

/// What one window contributes to the saved session (issue #46). `SessionCoordinator` decides when
/// this runs; `SessionStore` owns the file.
///
/// Capture reads only through existing public queries plus the one new
/// `TerminalSessions.sessionCapture(forTargetID:)`, so the four pane dictionaries stay
/// `@Published private` where they belong.
extension AppStore {
  /// This window's whole restorable state, right now.
  ///
  /// Runs on the main actor and must stay cheap: it is called on every coalesced save, and (via the
  /// ceiling) at a steady cadence while terminals are busy. It walks a few dozen small values and
  /// allocates no views — the expensive part, encoding, happens off the main actor in `SessionStore`.
  func captureWindowSession() -> WindowSession {
    WindowSession(
      windowKey: sessionKey.uuidString,
      frame: hostWindow.map { NSStringFromRect($0.frame) },
      isKey: hostWindow?.isKeyWindow ?? false,
      selectedTargetID: Self.targetIDString(for: selectedTargetID),
      targets: captureTargetSessions(),
      workroomSplits: captureWorkroomSplits(),
      expandedTargets: expandedTerminalTargets.isEmpty
        ? nil : expandedTerminalTargets.sorted())
  }

  private static let sessionLogger = Logger(
    subsystem: "com.developwithstyle.workroom", category: "session")

  /// Every target that currently owns panes, in a stable order so an unchanged layout produces an
  /// unchanged document — which is what lets the coordinator's equality gate drop the write.
  ///
  /// **The caps are enforced here, not only on read.** `SessionFile.sanitized()` drops anything over
  /// them at restore, so a capture that ignored them would let the app author a file it then
  /// truncates on every single launch — the user losing the same targets forever, silently. Applying
  /// the same limit at both ends means what is written is exactly what comes back, and the drop is
  /// logged the one time it happens rather than being invisible.
  private func captureTargetSessions() -> [TargetSession] {
    let active = terminals.activeTargetIDs.sorted()
    if active.count > SessionLimits.maxTargetsPerWindow {
      let message =
        "session capture is over the target cap — persisting "
        + "\(SessionLimits.maxTargetsPerWindow) of \(active.count)"
      Self.sessionLogger.notice("\(message, privacy: .public)")
    }
    return active.prefix(SessionLimits.maxTargetsPerWindow).compactMap { targetID in
      guard let captured = terminals.sessionCapture(forTargetID: targetID) else { return nil }

      // Tabs the bridge refuses (today: run tabs) drop out here, and the split leaf that pointed at
      // one collapses with them — `LayoutNode.capture` applies the same rule `PaneLayout.removingLeaf`
      // does, so a split can never be left addressing a pane that was not written.
      var keysByTabID: [TerminalTab.ID: String] = [:]
      var tabs: [TabSession] = []
      for tab in captured.tabs {
        guard tabs.count < SessionLimits.maxTabsPerTarget else { break }
        let key = tab.id.uuidString
        guard let session = TabSession(key: key, tab: tab) else { continue }
        keysByTabID[tab.id] = key
        tabs.append(session)
      }
      guard !tabs.isEmpty else { return nil }

      let split = captured.split.flatMap { layout in
        LayoutNode<String>.capture(layout) { keysByTabID[$0] }
      }
      return TargetSession(
        targetID: targetID, tabs: tabs, split: split,
        focusedKey: captured.focused.flatMap { keysByTabID[$0] },
        terminalCounter: captured.counter)
    }
  }

  /// The workroom-into-workroom split groups, with `SidebarID` leaves reduced to the same target-id
  /// strings `Defaults[.sidebarSelection]` and `workroomTabOrder` already persist — so no new id
  /// format ships, and `AppStore.sidebarID(forTargetID:in:)` resolves them back (dropping any that
  /// no longer exist).
  private func captureWorkroomSplits() -> [LayoutNode<String>] {
    workroomSplits.compactMap { layout in
      LayoutNode<String>.capture(layout) { Self.targetIDString(for: $0) }
    }
  }

  /// Write every live pane's scrollback to its sidecar (issue #144). Quit only — reading each
  /// pane's history is far too heavy for a coalesced save.
  ///
  /// The tab key must match what `captureTargetSessions` wrote for the same tab, or the sidecar
  /// belongs to nothing and is pruned the moment it is written.
  ///
  /// **Bounded by a wall-clock budget**, because this runs synchronously on the main thread inside
  /// `applicationShouldTerminate` — and on the SIGTERM path it runs *before* run commands are stopped.
  /// Per-pane cost is bounded in `GhosttySurfaceView.captureScrollback`; this bounds the total, so a
  /// window full of busy panes cannot turn a quit into a spinning beachball. A pane past the deadline
  /// restores with no text (tab keys are re-minted every launch, so there is no older sidecar for it
  /// to fall back on) — losing one pane's history beats hanging the quit for every pane.
  /// `isEnabled` is a parameter rather than a bare `Defaults` read so a test can drive the opt-out
  /// without mutating a shared preference domain (the single-writer constraint parallel test workers
  /// impose — see `SharedPrefDefaultsTests`).
  func captureScrollback(
    into store: SessionStore, isEnabled: Bool = Defaults[.persistScrollback],
    deadline: Date = Date() + 1.5
  ) {
    guard isEnabled else { return }
    var skipped = 0
    for targetID in terminals.activeTargetIDs {
      guard let captured = terminals.sessionCapture(forTargetID: targetID) else { continue }
      for tab in captured.tabs {
        // Run tabs are not persisted at all, so their output must not be either.
        guard tab.surface?.isRunCommandSurface != true else { continue }
        guard Date() < deadline else {
          skipped += 1
          continue
        }
        guard let text = tab.surface?.captureScrollback() else { continue }
        store.writeScrollback(text, forTabKey: tab.id.uuidString)
      }
    }
    if skipped > 0 {
      Self.sessionLogger.notice("scrollback capture ran out of budget — \(skipped) panes skipped")
    }
  }

  /// Tell the coordinator this window changed. Every dirty source funnels through here so there is
  /// one place to look when asking "what causes a save?".
  func markSessionDirty() {
    SessionCoordinator.shared.markDirty()
  }

  // MARK: Restore

  /// Adopt this window's saved session, once. Called from `attachWindow` — see the comment there for
  /// why not from the view initialiser.
  func claimSessionIfNeeded() {
    guard !didClaimSession else { return }
    didClaimSession = true
    // Every ⌘N window opens blank, matching how the persisted selection already behaves.
    guard claimsSavedSession else { return }
    guard
      let claimed = projectStore.claimSession(for: sessionKey, isLaunchWindow: isRestoreWindow)
    else { return }
    pendingSessionRestore = claimed
    // Keep the window's identity stable across launches: it now owns this session's slot.
    if let key = UUID(uuidString: claimed.windowKey) { sessionKey = key }
    // The session owns selection; `Defaults[.sidebarSelection]` (already loaded into
    // `pendingRestoreSelection`) stays as the cold-start fallback for a launch with no session file.
    // Feeding the session's value through the SAME field means `apply` needs no second branch.
    //
    // Assigned UNCONDITIONALLY, nil included: a saved window that had nothing selected must come back
    // with nothing selected. Overwriting only on non-nil would let the single-slot Defaults key —
    // last written by whichever OTHER window was active — decide this window's selection, which is
    // exactly the per-window authority the session file exists to provide.
    pendingRestoreSelection = claimed.selectedTargetID
  }

  /// Rehydrate the claimed session at the end of `apply(_:)`. One-shot: `apply` runs twice per
  /// bootstrap (`load("none")` then `load("fast")`), and reloads come through it too.
  func restorePersistedSessionIfPending(in projects: [Project]) {
    guard let session = pendingSessionRestore else { return }
    pendingSessionRestore = nil
    defer { projectStore.finishSessionRestore() }

    // Resolved once, not per tab: with the preference off, restore hands every pane a closure that
    // returns nothing, so nothing is read and nothing is replayed. The layout still comes back.
    let coordinator = projectStore.sessionCoordinator
    let readScrollback: (String) -> String? =
      Defaults[.persistScrollback] ? { coordinator.scrollback(forTabKey: $0) } : { _ in nil }

    var restoredTargetIDs: Set<TerminalTarget.ID> = []
    for saved in session.targets {
      // A target that no longer resolves — its workroom was deleted between launches — is dropped
      // whole, the same self-heal `validatedSelection` and `pruneWorkroomSplitToLiveLeaves` apply.
      guard let sid = Self.sidebarID(forTargetID: saved.targetID, in: projects),
        let target = target(for: sid)
      else { continue }
      guard terminals.restore(saved, for: target, scrollback: readScrollback) > 0 else { continue }
      restoredTargetIDs.insert(target.id)
    }

    // The workroom-into-workroom split groups (issue #23). A leaf whose workroom is gone collapses,
    // and a group left with fewer than two leaves dissolves — `materialize` enforces that, so a
    // one-workroom "group" can never reach the live model.
    workroomSplits = session.workroomSplits.compactMap { saved in
      saved.materialize { Self.sidebarID(forTargetID: $0, in: projects) }
    }
    // Sidebar terminal-subtree expansion (issue #30). Only for targets that actually came back —
    // an expand flag pointing at nothing would render an empty disclosure.
    expandedTerminalTargets = Set(session.expandedTargets ?? []).intersection(restoredTargetIDs)

    refreshSelectionHasTabs()
  }
}

/// alternate screen. So a pane that has produced scrollback before, and whose `SURFACE` reads false
/// now, has a TUI up.
///
/// The gap is a pane that launches a TUI before producing any output — indistinguishable from a
/// short session, so its frame is captured. A real alt-screen query would close it; see TODOS.md.
/// Rows of history worth asking libghostty for at quit.
///
/// `read_text` has no length parameter — it materialises the WHOLE history as one string, and only
/// then does `TerminalCapture.tidy` keep the last `maxScrollbackBytes` of it. The app sets no
/// `scrollback-limit`, so that history is bounded only by ghostty's own default (megabytes per
/// surface), and this runs serially for every pane inside `applicationShouldTerminate`. A pane that
/// logged all day would turn a quit into a multi-second hang for output that is discarded anyway.
///
/// 10,000 rows sits above what `maxScrollbackBytes` can hold at a typical row width, so a pane whose
/// history would have survived the byte cap is not skipped by this one. Past it, the viewport alone
/// is captured — what you were actually looking at, which is the part worth keeping. Against
/// ghostty's byte-based default (~130,000 rows at 80 columns) that is still an order-of-magnitude
/// bound on the read.
static let maxCaptureRows: UInt64 = 10_000

/// Pure form of the row guard, so the bound is unit-testable without a live surface.
///
/// Absent metrics read as "worth trying": a surface that has never reported geometry has nothing to
/// read anyway, and the guard is about panes that report a LOT, not panes that report nothing.
nonisolated static func shouldReadHistory(totalRows: UInt64?) -> Bool {
  (totalRows ?? 0) <= maxCaptureRows
}

func captureScrollback(maxBytes: Int = SessionLimits.maxScrollbackBytes) -> String? {
  let historyIsWorthReading = Self.shouldReadHistory(totalRows: scrollbarMetrics?.total)
  let history = historyIsWorthReading ? readText(tag: GHOSTTY_POINT_SURFACE) : nil
  // The alternate-screen inference only holds when the `SURFACE` read actually ran: `history == nil`
  // because we CHOSE not to read it says nothing about a TUI, and treating it as one would skip the
  // viewport too and capture nothing at all — the exact panes with the most worth keeping. (An alt
  // screen has no scrollback of its own, so a TUI never trips the row guard and detection is intact.)
  let isAlternateScreen =
    historyIsWorthReading
    && Self.shouldSkipViewport(
      hasHistoryNow: history != nil, everHadScrollback: everHadScrollback)
  // The viewport is otherwise always read: `SURFACE` is history ONLY, so gating it on history
  // existing would capture nothing at all for a short session — most panes, most of the time.
  let visible = isAlternateScreen ? nil : readText(tag: GHOSTTY_POINT_VIEWPORT)
  let combined = [history, visible].compactMap { $0 }.joined(separator: "\n")
  guard !combined.isEmpty else { return nil }
  return TerminalCapture.tidy(combined, maxBytes: maxBytes)
}

/// Pure form of the rule above, so it can be unit-tested without a live surface.
nonisolated static func shouldSkipViewport(hasHistoryNow: Bool, everHadScrollback: Bool) -> Bool {
  !hasHistoryNow && everHadScrollback
}

/// Replay a previous session's text into this surface, once, followed by a divider marking where
/// restored history ends and the live shell begins.
///
/// `write_buffer` feeds the terminal parser as if the child had emitted the bytes — verified to
/// work on an EXEC (real PTY) surface, with the shell still executing commands afterwards (#144
/// spike). The bytes are rendered text, never escape sequences, and control bytes are stripped on
/// the way in, so this cannot leave the parser mid-sequence.
private func replayRestoredScrollback() {
  guard !didReplayScrollback, let surface, let provider = restoredScrollback else { return }
  didReplayScrollback = true
  // Released as soon as it has run: the text is now the terminal's own scrollback, and keeping a
  // second copy on the view would double the memory cost of every restored pane for no purpose.
  restoredScrollback = nil
  guard let restored = provider(), !restored.isEmpty else { return }
  var bytes = Array(Self.replayPayload(for: restored).utf8)
  ghostty_surface_write_buffer(surface, &bytes, UInt(bytes.count))
}

/// The exact bytes replayed into a restored pane: the captured text with **CRLF** line endings,
/// then the divider.
///
/// The CR is the whole point. `read_text` returns lines separated by bare `\n`, but a terminal
/// treats LF as "down one row, keep the column" — CR is what returns to column zero. Replaying the
/// captured text unchanged therefore staircases every line further right than the last, which is
/// exactly what it looked like. Normalise any existing CRLF down to LF first so this cannot double
/// the CR on text that already had it.
///
/// Pure and `nonisolated` so the rule is unit-testable without a surface.

