5	/// The single app-level coordinator for the multi-window world (issue #70). Each window owns its own
6	/// `AppStore` (per-window selection, terminals, splits, run state); this registry is the *only*
7	/// shared coordination point above them, for the things that are genuinely app-scoped:
8	///
9	/// - **Key/active routing** — the `AppDelegate` key-event monitor and a terminal surface's
10	///   context-menu actions act on whichever window is key (`keyStore`).
11	/// - **Last-active capture** — `lastActiveStore` tracks the most recent *workroom* window to become
12	///   key, captured before any modal (quit alert / Settings) can steal key status, so quit-time
13	///   persistence reads the right window.
14	/// - **Aggregation** — the Dock badge (and menu-bar item) sum across every window's notifications.
15	/// - **Run-command ownership** — a workroom's run command is single-owner across windows; a second
16	///   window's Run focuses the owner instead of forking a duplicate server (issue #70 / issue #7).
17	/// - **Quit/close de-dup** — `isTerminating` suppresses the per-window close prompt during a quit.
18	///
19	/// Per-window logic stays in `AppStore`; this holds only weak references, so closed windows fall out
20	/// on the next prune.
21	@MainActor
22	final class WindowRegistry: ObservableObject {
23	  static let shared = WindowRegistry()
24	
25	  private final class Entry {
26	    weak var window: NSWindow?
27	    weak var store: AppStore?
28	    init(window: NSWindow, store: AppStore) {
29	      self.window = window
30	      self.store = store
31	    }
32	  }
33	  private var entries: [Entry] = []
34	
35	  /// True while the app is terminating, so a window's close handler doesn't prompt/stop run commands
36	  /// a second time on top of `applicationShouldTerminate` (issue #70, OV #10).
37	  var isTerminating = false
38	
39	  /// The most recent registered (workroom) window to become key. Updated only for registered windows,
40	  /// so a modal alert / Settings becoming key never overwrites it — quit persistence can trust it.
41	  private(set) weak var lastActiveStore: AppStore?
42	
43	  /// Combined unread notification count across every window — drives the menu-bar label + Dock badge
44	  /// (issue #70). `@Published` so the `MenuBarExtra` label re-renders as any window's count changes.
45	  @Published private(set) var aggregateUnread = 0
46	
47	  init() {
48	    // Track the active workroom window. Only registered windows update `lastActiveStore`, so the quit
49	    // alert / Settings / menu-bar popover becoming key leaves the last *workroom* selection intact.
50	    NotificationCenter.default.addObserver(
51	      forName: NSWindow.didBecomeKeyNotification, object: nil, queue: .main
52	    ) { [weak self] note in
53	      MainActor.assumeIsolated {
54	        guard let self, let window = note.object as? NSWindow,
55	          let store = self.store(for: window)
56	        else { return }
57	        self.lastActiveStore = store
58	        // Which window was key is part of the saved session — it decides where the user lands after
59	        // a restore (issue #46).
60	        SessionCoordinator.shared.markDirty()
61	        // Bringing a window forward makes its selection the most recent one (issue #132). Without
62	        // this, ⌘` to another window leaves the switcher's MRU head pointing at the window you left,
63	        // so the next ⌥Tab tap flips somewhere you didn't come from.
64	        SwitcherRecency.shared.recordWorkroom(store: store, sid: store.selectedTargetID)
65	      }
66	    }
67	    // Drop a window as it closes (issue #46). `unregister` previously had NO caller: entries were
68	    // only ever cleared by `prune()` noticing the weak reference had died, which happens whenever the
69	    // next unrelated lookup runs — so a closed window scheduled no save, and the session file kept
70	    // describing it until something else happened to mark the session dirty. Filtered to registered
71	    // workroom windows, so Settings/About/quick terminal closing here is a no-op.
72	    NotificationCenter.default.addObserver(
73	      forName: NSWindow.willCloseNotification, object: nil, queue: .main
74	    ) { [weak self] note in
75	      MainActor.assumeIsolated {
76	        guard let self, let window = note.object as? NSWindow, self.store(for: window) != nil
77	        else { return }
78	        self.unregister(window: window)
79	      }
80	    }
81	  }
