83	  // MARK: Registration
84	
85	  /// Register (or re-register) a window with its store. Idempotent — `WindowAccessor` may resolve the
86	  /// same window more than once. Prunes any dead entries while here.
87	  func register(window: NSWindow, store: AppStore) {
88	    prune()
89	    if let existing = entries.first(where: { $0.window === window }) {
90	      existing.store = store
91	    } else {
92	      entries.append(Entry(window: window, store: store))
93	    }
94	    assignWindowNumberIfNeeded(store)
95	    if lastActiveStore == nil { lastActiveStore = store }
96	    recomputeBadge()
97	    // The saved session is rebuilt from the live windows (issue #46), and the window layer publishes
98	    // through none of the store's own publishers — so opening a window has to say so itself.
99	    SessionCoordinator.shared.markDirty()
100	  }
101	
102	  /// Give a newly registered window the smallest unused positive number, so the untitled-window
103	  /// fallback reads "Window 1", "Window 2", … and a closed window's number is reclaimed by the next
104	  /// new window (macOS untitled-document style). Assigned once per store (0 = not yet numbered).
105	  private func assignWindowNumberIfNeeded(_ store: AppStore) {
106	    guard store.windowNumber == 0 else { return }
107	    let used = Set(entries.compactMap { $0.store?.windowNumber }.filter { $0 > 0 })
108	    var n = 1
109	    while used.contains(n) { n += 1 }
110	    store.windowNumber = n
111	  }
