113	  func unregister(window: NSWindow) {
114	    entries.removeAll { $0.window === window || $0.window == nil }
115	    recomputeBadge()
116	    // Without this a closed window is never noticed, and comes back on the next launch. The quit
117	    // freeze is what stops the same signal erasing the session as windows close during termination.
118	    SessionCoordinator.shared.markDirty()
119	  }
