121	  private func prune() {
122	    entries.removeAll { $0.window == nil || $0.store == nil }
123	  }
124	
125	  // MARK: Lookup
126	
127	  /// Every live window's store.
128	  var allStores: [AppStore] {
129	    prune()
130	    return entries.compactMap(\.store)
131	  }
132	
133	  func store(for window: NSWindow?) -> AppStore? {
134	    guard let window else { return nil }
135	    return entries.first { $0.window === window }?.store
136	  }
137	
138	  /// The store of the window that should receive a global key event / surface action: the key window
139	  /// if it's one of ours, else the last active workroom window, else any.
140	  var keyStore: AppStore? {
141	    store(for: NSApp.keyWindow) ?? lastActiveStore ?? allStores.first
142	  }
143	
144	  /// The frame size a *new* window should open at: the current (last-active, else any) window's full
145	  /// frame size, so a new window opens at exactly the existing window's size (issue #70). Frame, not
146	  /// content, size — this app's full-width titlebar toolbar makes the two differ. `nil` when there's
147	  /// no existing window (the launch window), which then restores its own saved frame / a default.
148	  var preferredNewWindowSize: CGSize? {
149	    let window = lastActiveStore?.hostWindow ?? allStores.compactMap(\.hostWindow).first
150	    return window?.frame.size
151	  }
152	
153	  /// The window store that owns the terminal tab `tabID` (each tab id is unique across windows), for
154	  /// routing an OS-notification click to the right window (issue #70, OV #4).
155	  func ownerOf(tabID: TerminalTab.ID) -> AppStore? {
156	    allStores.first { $0.terminals.containsTab(tabID) }
157	  }
