161	  /// Cycle key focus to the next/previous app window — the "Move focus to next window" shortcut
162	  /// (⌘` forward, ⇧⌘` backward), driven by the `AppDelegate` key monitor because the focused
163	  /// terminal surface otherwise swallows the backtick as input. Cycles every workroom window plus
164	  /// the quick terminal (issue #39), the windows the user actually works in — deliberately not the
165	  /// Settings / About panels. Works in front-to-back z-order: forward surfaces the window just
166	  /// behind the front and sends the old front to the back; backward surfaces the backmost — so
167	  /// repeated presses rotate through *all* windows instead of bouncing between the front two.
168	  func cycleWindows(forward: Bool) {
169	    let cycleable = NSApp.orderedWindows.filter(isCycleableWindow)
170	    guard let plan = Self.cyclePlan(ordered: cycleable, forward: forward) else { return }
171	    plan.front.makeKeyAndOrderFront(nil)
172	    plan.sendBack?.orderBack(nil)
173	  }
