175	  /// A window ⌘`/⇧⌘` should cycle through: a visible, focusable workroom window (one we registered)
176	  /// or the quick terminal. Excludes panels, the menu-bar status item's window, and anything that
177	  /// can't become key.
178	  ///
179	  /// Internal rather than private so a test can assert the switcher rail's panel is rejected — the
180	  /// `canBecomeKey` guard is what excludes it, and `SwitcherPanel` relies on that staying true.
181	  func isCycleableWindow(_ window: NSWindow) -> Bool {
182	    guard window.isVisible, window.canBecomeKey else { return false }
183	    return store(for: window) != nil || window is QuickTerminalWindow
184	  }
185	
186	  /// Pure rotation math for `cycleWindows`, extracted so it's unit-testable without live z-ordering.
187	  /// `ordered` is the cycleable windows front-to-back. Returns the window to bring forward and, for
188	  /// the forward direction, the old front window to push to the back (so the rotation visits every
189	  /// window rather than ping-ponging between the front two). nil when there's nothing to cycle to.
190	  nonisolated static func cyclePlan<W>(ordered: [W], forward: Bool) -> (front: W, sendBack: W?)? {
191	    guard ordered.count > 1 else { return nil }
192	    return forward ? (ordered[1], ordered[0]) : (ordered[ordered.count - 1], nil)
