205	  // MARK: Run-command ownership
206	
207	  /// The other window already running `target`'s run command, if any. Derived from each window's live
208	  /// `runStates` (no separate map to drift): a second window's Run focuses this owner instead of
209	  /// forking a duplicate dev server on the same port (issue #70 / issue #7).
210	  func runOwner(for target: TerminalTarget.ID, excluding: AppStore) -> AppStore? {
211	    allStores.first { $0 !== excluding && ($0.runStates[target]?.isRunning ?? false) }
212	  }
