214	  // MARK: Quit
215	
216	  /// Any window with a live run command — gates the graceful-stop-on-quit (issue #7 / #70).
217	  var hasAnyLiveRunCommand: Bool { allStores.contains(where: \.hasLiveRunCommand) }
218	
219	  /// Ctrl-C every window's live run commands and let them exit before the process dies, so dev
220	  /// servers release their ports/pidfiles instead of being orphaned by the OS hangup (issue #7).
221	  /// Calls `completion` once all windows have stopped (or each one's timeout elapses).
222	  func gracefullyStopAllWindows(timeout: TimeInterval, completion: @escaping () -> Void) {
223	    let live = allStores.filter(\.hasLiveRunCommand)
224	    guard !live.isEmpty else {
225	      completion()
226	      return
227	    }
228	    let group = DispatchGroup()
229	    for store in live {
230	      group.enter()
231	      store.gracefullyStopAllRunCommands(timeout: timeout) { group.leave() }
232	    }
233	    group.notify(queue: .main) { completion() }
234	  }
235	}
